; RESET entry.
;
; Sets up the stack, configures ports 1 and 2, and installs the interrupt soft
; vectors before entering the main firmware.
reset:
        LDS     #$0400                  ; stack top - external RAM lies below $0400
        LDAA    #$10
        STAA    PORT1
        CLR     P1DDR
        LDAA    #$11
        STAA    P2DDR
        STAA    PORT2
        LDD     #$F147
        STD     >softVecTof
        STD     >softVecIcf
        STD     >softVecSwi
        LDD     #$F14C
