        STAB    PORT4
        LDAA    #$AB
        STAA    P4DDR
        LDD     #$0395
        STAA    >$0040
        STAB    >$0040
        LDAA    #$08
        STAA    TCSR
        LDD     COUNTH
        ADDD    #$3415
        STD     OCRH
        LDAA    TRCSR
        LDAA    RDR
        LDAA    #$0C
        STAA    RMCR
        LDAA    #$08
        STAA    TRCSR
        LDAA    TRCSR
        LDAA    RDR
        JSR     LEEB1
        JSR     LEE9A
        JSR     LD849
        JSR     LD3E5
        JSR     LE9A5
        JSR     LECCB
        JSR     LB2A3
        JSR     LEED2
        JSR     LA210
        LDD     #$F87F
